//! The ~1 MB Wikipedia-like page (generated by user/webbench/src/wikigen.rs): parse, style and
//! lay out, with times and sizes printed (run `cargo test --release ... wiki -- --nocapture`
//! for real numbers).

#[path = "../../../webbench/src/wikigen.rs"]
pub mod wikigen;

use super::raster::SysMeasurer;
use crate::api::*;

#[test]
fn wiki_page_1mb() {
    let html = wikigen::wiki_page(1 << 20, 42);
    assert!(html.len() > 1_000_000, "{}", html.len());
    let t0 = std::time::Instant::now();
    let mut d = Document::parse(
        html.as_bytes(),
        "https://wiki.example/wiki/Milk",
        Some("text/html; charset=utf-8"),
    );
    let t1 = std::time::Instant::now();
    let (n_entries, height) = {
        let dl = d.layout(&Viewport::new(1024, 768), &SysMeasurer);
        (dl.entries.len(), dl.height)
    };
    let t2 = std::time::Instant::now();
    d.layout(&Viewport::new(800, 768), &SysMeasurer);
    let t3 = std::time::Instant::now();
    d.layout(&Viewport::new(800, 768), &SysMeasurer);
    let t4 = std::time::Instant::now();
    let st = d.stats();
    std::println!(
        "wiki: {} bytes, parse {:?}, style+layout+paint {:?}, relayout at 800 {:?}, cached {:?}; {} nodes, {} rules, {} boxes, {} items, ~{} KB, height {}",
        html.len(),
        t1 - t0,
        t2 - t1,
        t3 - t2,
        t4 - t3,
        st.nodes,
        st.rules,
        st.boxes,
        n_entries,
        st.approx_bytes / 1024,
        height
    );
    assert!(st.nodes > 50_000);
    assert!(height > 20_000);
    // The narrow layout hides the sidebar (media query) and the find index works.
    assert!(!d.find("milk", false).is_empty());
    assert!(d.main_content().is_some());
    assert!(d.fragment_y("References").is_some_and(|y| y > 10_000));
}

#[test]
fn struct_sizes() {
    use core::mem::size_of;
    std::println!(
        "sizes: LBox {} Style {} Node {} Element {} Frag {} Entry {} Decl {}",
        size_of::<crate::layout::LBox>(),
        size_of::<crate::style::types::Style>(),
        size_of::<crate::dom::Node>(),
        size_of::<crate::dom::Element>(),
        size_of::<crate::layout::Frag>(),
        size_of::<Entry>(),
        size_of::<crate::style::props::Decl>(),
    );
}
